package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var Emp EmpRec

var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func parseDigits(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			n = n * 10
		} else if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(val decimal.Decimal, picture string) string {
	// split picture
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := len(fracPic)
	// count int slots
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// truncate toward zero to fracDigits
	val = val.Truncate(int32(fracDigits))
	shifted := val.Shift(int32(fracDigits)).Truncate(0)
	s := shifted.String()
	// s is integer string, no decimal, no sign (non-negative)
	// remove any sign/exponent (shouldn't happen)
	if strings.Contains(s, "e") || strings.Contains(s, "E") {
		// fallback expand
		s = shifted.StringFixed(0)
	}
	// ensure numeric
	// pad fraction/integer split
	if len(s) <= fracDigits {
		// need leading zeros
		s = strings.Repeat("0", fracDigits+1-len(s)) + s
	}
	var intDigits, fracDigitsStr string
	if fracDigits > 0 {
		fracDigitsStr = s[len(s)-fracDigits:]
		intDigits = s[:len(s)-fracDigits]
	} else {
		fracDigitsStr = ""
		intDigits = s
	}
	// strip leading zeros for intDigits? keep at least "0"
	intDigits = strings.TrimLeft(intDigits, "0")
	if intDigits == "" {
		intDigits = "0"
	}
	// drop high-order digits
	if len(intDigits) > intSlots {
		intDigits = intDigits[len(intDigits)-intSlots:]
	}
	// pad left with zeros to intSlots
	padded := strings.Repeat("0", intSlots-len(intDigits)) + intDigits
	// find significant position
	sigPos := intSlots - 1
	for i := 0; i < intSlots; i++ {
		if padded[i] != '0' {
			sigPos = i
			break
		}
	}
	// build integer part output
	var b strings.Builder
	slotIdx := 0
	for _, ch := range intPic {
		switch ch {
		case 'Z', '9':
			d := padded[slotIdx]
			if slotIdx < sigPos {
				if ch == 'Z' {
					b.WriteByte(' ')
				} else {
					b.WriteByte(d)
				}
			} else {
				b.WriteByte(d)
			}
			slotIdx++
		case ',':
			// suppressed if no significant digit to the left
			// significant digit to left exists iff sigPos < slotIdx... need check:
			// digits left are slots 0..slotIdx-1; significant among them?
			if sigPos < slotIdx {
				// wait: if sigPos >= slotIdx, all left digits are suppressed
				b.WriteByte(' ')
			} else {
				// sigPos < slotIdx means first significant is left of comma
				b.WriteByte(',')
			}
			// Actually condition: comma prints iff sigPos < slotIdx
			// Above branches swapped? Let's correct:
			// We wrote if sigPos < slotIdx -> space, else comma — wrong.
			// Fix by rewriting: we need to undo. Easiest: get last byte and fix.
		default:
			b.WriteByte(byte(ch))
		}
	}
	// Fix commas: we inverted logic above. Recompute correctly by rebuilding.
	// Rebuild correctly:
	b.Reset()
	slotIdx = 0
	for _, ch := range intPic {
		switch ch {
		case 'Z', '9':
			d := padded[slotIdx]
			if slotIdx < sigPos {
				if ch == 'Z' {
					b.WriteByte(' ')
				} else {
					b.WriteByte(d)
				}
			} else {
				b.WriteByte(d)
			}
			slotIdx++
		case ',':
			if sigPos < slotIdx {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		default:
			b.WriteByte(byte(ch))
		}
	}
	intPart := b.String()
	var out string
	if fracDigits > 0 {
		out = intPart + "." + fracDigitsStr
	} else {
		out = intPart
	}
	_ = neg
	// width should equal len(picture); ensure
	if len(out) < len(picture) {
		out = strings.Repeat(" ", len(picture)-len(out)) + out
	}
	return out
}

func formatCount(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	v = v % mod
	if v < 0 {
		v += mod
	}
	s := fmt.Sprintf("%d", v)
	if len(s) > width {
		s = s[len(s)-width:]
	}
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func modDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order digits: modulo 10^intDigits at given scale
	modInt := decimal.NewFromInt(1).Shift(int32(intDigits)) // 10^intDigits
	// scale the value
	scaled := v.Shift(scale).Truncate(0)
	m := decimal.NewFromInt(1).Shift(int32(intDigits) + scale) // 10^(intDigits+scale)
	// modulo keeping sign
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Neg()
	}
	r := scaled.Mod(m)
	if neg {
		r = r.Neg()
	}
	return r.Shift(-scale)
}

func MainPara() {
	// OPEN INPUT EMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		inputLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// Scanner strips \n and \r\n; need to remove trailing \r if any left
			line = strings.TrimSuffix(line, "\r")
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0
	inputOpen = true
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	inputOpen = false
	GrandPara()
}

func ReadPara() {
	if !inputOpen {
		WsEofFlag = "Y"
		return
	}
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	Emp.ErId = line[0:5]
	Emp.ErDept = line[5:8]
	hStr := line[8:12]
	rStr := line[12:17]
	Emp.ErHours = decimal.New(parseDigits(hStr), -1)
	Emp.ErRate = decimal.New(parseDigits(rStr), -2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = Emp.ErDept
		WsFirstFlag = "N"
	} else {
		if Emp.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = Emp.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if Emp.ErHours.GreaterThan(forty) {
		WsRegHours = decimal.NewFromInt(40)
		// scale 1: 40.0
		WsRegHours = decimal.New(400, -1)
		WsOtHours = Emp.ErHours.Sub(forty)
		WsOtHours = WsOtHours.Truncate(1)
		// store truncates to 9(3)V9 with low-order? fits
		WsOtHours = modDecimal(WsOtHours, 3, 1)
	} else {
		WsRegHours = Emp.ErHours.Truncate(1)
		WsRegHours = modDecimal(WsRegHours, 3, 1)
		WsOtHours = decimal.NewFromInt(0)
	}
	oneHalf := decimal.New(15, -1)
	val := WsRegHours.Mul(Emp.ErRate).Add(WsOtHours.Mul(Emp.ErRate).Mul(oneHalf))
	WsGross = val.Round(2)
	WsGross = modDecimal(WsGross, 7, 2)
	WsDeptTotal = WsDeptTotal.Add(WsGross).Truncate(2)
	WsDeptTotal = modDecimal(WsDeptTotal, 9, 2)
	WsDeptCount = (WsDeptCount + 1) % 1000
	WsGrandTotal = WsGrandTotal.Add(WsGross).Truncate(2)
	WsGrandTotal = modDecimal(WsGrandTotal, 11, 2)
	WsGrandCount = (WsGrandCount + 1) % 100000
	WsHoursEd = formatEdited(Emp.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(Emp.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", padRight(Emp.ErId, 5), padRight(Emp.ErDept, 3), WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", padRight(WsPrevDept, 3), formatCount(WsDeptCount, 3), WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("GRAND TOTAL (%s): %s\n", formatCount(WsGrandCount, 5), WsGrandEd)
}

func main() {
	MainPara()
}

